source('R/stile.R');d<-read.csv('dati/progetti/foraminiferi.csv');d$date<-as.Date(d$date);out<-'risultati/P02';dir.create(out,recursive=TRUE,showWarnings=FALSE)
verifica('integrita delle coppe',nrow(d)==36&&!anyDuplicated(paste(d$trap_year,d$cup_id))&&all(d$depth_m==170))
verifica('ordine delle sintesi',all(d$diam_min_um<=d$diam_mean_um)&all(d$diam_mean_um<=d$diam_max_um))
mese<-as.integer(format(d$date,'%m'));d$season<-ifelse(mese%in%c(10,11,12,1,2,3),'Ott-Mar','Apr-Set');cols<-c('Ott-Mar'=geo[1],'Apr-Set'=geo[2]);labanno<-function(x)paste0(substr(x,1,4),'/',substr(x,8,9))
salva('P02','F01',ggplot(d,aes(date,diam_mean_um,colour=season))+geom_point(size=2.5)+scale_colour_manual(values=cols)+scale_x_date(breaks=as.Date(c('2006-01-01','2009-01-01','2012-01-01')),date_labels='%Y')+labs(x='Data centrale della coppa',y='Diametro massimo medio (µm)'))
counts<-as.data.frame(table(campagna=d$trap_year,fascia=d$season));salva('P02','F02',ggplot(counts,aes(fascia,campagna,fill=Freq))+geom_tile(colour=paper,linewidth=1)+geom_text(aes(label=Freq),size=7,colour=ink)+scale_fill_gradient(low=paper,high='#8AC6BE')+scale_y_discrete(labels=labanno)+guides(fill='none')+labs(x='Fascia calendario',y='Campagna'))
agg<-aggregate(diam_mean_um~trap_year+season,d,mean);w<-reshape(agg,idvar='trap_year',timevar='season',direction='wide');pairs<-w[complete.cases(w),];pairs<-pairs[order(pairs$trap_year),];names(pairs)<-sub('diam_mean_um.','',names(pairs),fixed=TRUE);pairs$delta<-pairs[['Ott-Mar']]-pairs[['Apr-Set']];delta<-pairs$delta;n<-length(delta);est<-mean(delta);tt<-t.test(delta);ct<-tt$conf.int
verifica('quattro campagne complete',n==4&&length(unique(d$trap_year))==6)
pa<-rbind(data.frame(campagna=pairs$trap_year,fascia='Apr-Set',diametro=pairs[['Apr-Set']]),data.frame(campagna=pairs$trap_year,fascia='Ott-Mar',diametro=pairs[['Ott-Mar']]))
salva('P02','F03',ggplot(pa,aes(fascia,diametro,group=campagna,colour=campagna))+geom_line(linewidth=.7)+geom_point(size=2.6)+scale_colour_manual(values=geo[1:4],labels=labanno)+guides(colour=guide_legend(nrow=2))+labs(x='Fascia calendario',y='Media delle coppe (µm)'))
salva('P02','F04',ggplot(pairs,aes(delta,trap_year))+geom_vline(xintercept=0,colour=geo[6],linetype=2)+geom_segment(aes(x=0,xend=delta,yend=trap_year),colour=geo[1],linewidth=.7)+geom_point(colour=geo[1],size=2.8)+scale_y_discrete(labels=labanno)+labs(x='Differenza fra fasce (µm)',y='Campagna'))
ix<-as.matrix(read.csv('dati/progetti/piani_ricampionamento/paleo_years.csv'));boot<-apply(ix,1,function(i)mean(delta[i]));cb<-quantile(boot,c(.025,.975),type=7)
verifica('piano su quattro campagne',nrow(ix)==4000&&ncol(ix)==4&&all(ix>=1&ix<=4))
salva('P02','F05',ggplot(data.frame(delta=boot),aes(delta))+geom_histogram(bins=25,fill=geo[1],colour=paper,linewidth=.2)+geom_vline(xintercept=0,colour=geo[6],linetype=2)+geom_vline(xintercept=cb,colour=geo[2],linetype=3)+labs(x='Media ricampionata (µm)',y='Ricampionamenti'))
S<-as.matrix(expand.grid(rep(list(c(-1,1)),4)));null<-as.numeric(S%*%delta)/4;ps<-mean(abs(null)>=abs(est)-1e-12);nd<-data.frame(valore=null,probabilita=1/16,estremo=abs(null)>=abs(est)-1e-12)
verifica('enumerazione simmetrica',nrow(S)==16&&abs(mean(null))<1e-12&&all(sort(null)==sort(-null)))
verifica('risoluzione del test',ps>=2/16&&abs(ps*16-round(ps*16))<1e-12)
salva('P02','F06',ggplot(nd,aes(valore,probabilita,colour=estremo))+geom_segment(aes(xend=valore,yend=0),linewidth=.8)+geom_point(size=2.4)+scale_colour_manual(values=c('FALSE'=geo[1],'TRUE'=geo[3]),labels=c('Centrale','Almeno altrettanto estremo'))+guides(colour='none')+scale_y_continuous(breaks=c(0,1/16),labels=c('0','1/16'))+labs(x='Media sotto cambio di segno (µm)',y='Probabilità'))
loo<-data.frame(campagna=pairs$trap_year,stima=sapply(1:4,function(j)mean(delta[-j])))
salva('P02','F07',ggplot(loo,aes(stima,campagna))+geom_vline(xintercept=est,colour=geo[2],linetype=2)+geom_point(colour=geo[1],size=3)+scale_y_discrete(labels=labanno)+labs(x='Differenza media (µm)',y='Campagna esclusa'))
a<-d$diam_mean_um[d$season=='Ott-Mar'];b<-d$diam_mean_um[d$season=='Apr-Set'];naive<-t.test(a,b);naive_diff<-mean(a)-mean(b)
comp<-data.frame(metodo=c('Coppe\naggregate','Campagne\nappaiate'),stima=c(naive_diff,est),low=c(naive$conf.int[1],ct[1]),high=c(naive$conf.int[2],ct[2]))
salva('P02','F08',ggplot(comp,aes(stima,metodo))+geom_vline(xintercept=0,colour=geo[6],linetype=2)+geom_errorbarh(aes(xmin=low,xmax=high),colour=geo[2],height=.15,linewidth=.9)+geom_point(colour=geo[1],size=3)+scale_x_continuous(breaks=c(-25,0,25,50))+labs(x='Differenza stimata (µm)',y=NULL))
verifica('differenze e coppie coerenti',abs(est-(mean(pairs[['Ott-Mar']])-mean(pairs[['Apr-Set']])))<1e-10)
write.csv(pairs,file.path(out,'campagne_appaiate.csv'),row.names=FALSE);write.csv(counts,file.path(out,'copertura.csv'),row.names=FALSE);write.csv(data.frame(delta=boot),file.path(out,'bootstrap.csv'),row.names=FALSE);write.csv(nd,file.path(out,'segni.csv'),row.names=FALSE);write.csv(loo,file.path(out,'influenza.csv'),row.names=FALSE)
jsonlite::write_json(list(n_coppe=36,n_campagne=6,n_coppie=4,campagne=pairs,stima=est,se=sd(delta)/2,IC_t=ct,p=tt$p.value,IC_boot=cb,p_segni=ps,naive_diff=naive_diff,naive_p=naive$p.value,loo=loo,esiti_bootstrap=length(unique(round(boot,8)))),file.path(out,'valori.json'),pretty=TRUE,digits=12,auto_unbox=TRUE)
